proc publish*(s: ModuleServices, event: LcnNSStorageFetchFetchReadinessChangedEvent): Result[void, InvocationFailure] =
  ## Publishes `lcn.storage_fetch.fetch_readiness_changed_event` through the instance's publish callback.
  let data = encode(event).valueOr:
    return err(moduleError("the event does not match its schema: " & error))
  s.publishEncoded("lcn.storage_fetch.fetch_readiness_changed_event", data)

proc publishScoped*(s: ModuleServices, event: LcnNSStorageFetchFetchReadinessChangedEvent): Result[void, InvocationFailure] =
  ## Publishes `lcn.storage_fetch.fetch_readiness_changed_event` through the active provider entry (INTERFACE §2.9.3).
  let data = encode(event).valueOr:
    return err(moduleError("the event does not match its schema: " & error))
  s.publishScopedEncoded("lcn.storage_fetch.fetch_readiness_changed_event", data)

proc routeFetchFakeModule[T](instance: T, bare: string, params: openArray[byte]): Result[seq[byte], InvocationFailure] =
  mixin `fetch_readiness`, `read_object`, `set_fault`, `set_readiness`, `stat_object`
  let request = ?kitValidator().checkedRequest(bare, params)
  if bare == "fetch_readiness":
    let response = ?`fetch_readiness`(instance, fromChecked(LcnNSStorageFetchFetchReadinessRequest, request))
    return encodedResponse(encode(response))
  if bare == "read_object":
    let response = ?`read_object`(instance, fromChecked(LcnNSStorageFetchReadObjectRequest, request))
    return encodedResponse(encode(response))
  if bare == "set_fault":
    let response = ?`set_fault`(instance, fromChecked(FetchFakeSetFaultRequest, request))
    return encodedResponse(encode(response))
  if bare == "set_readiness":
    let response = ?`set_readiness`(instance, fromChecked(FetchFakeSetReadinessRequest, request))
    return encodedResponse(encode(response))
  if bare == "stat_object":
    let response = ?`stat_object`(instance, fromChecked(LcnNSStorageFetchStatObjectRequest, request))
    return encodedResponse(encode(response))
  discard request
  err(failure(ecMethodNotFound, "unknown method " & bare))

